package org.mockito.internal.stubbing.defaultanswers;

import java.io.*;
import java.io.Serializable;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import org.javassist.MethodProxy;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import org.mockito.cglib.proxy.MethodInterceptor;
import org.mockito.cglib.proxy.MethodProxy;
import org.mockito.exceptions.Reporter;
import org.mockito.internal.creation.jmock.ClassImposterizer;
import org.mockito.internal.debugging.Location;
import org.mockito.internal.util.ObjectMethodsGuru;
import org.mockito.internal.util.reflection.FieldAccess;
import org.mockito.invocation.InvocationOnMock;
import org.mockito.stubbing.Answer;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class ThrowingInterceptor_intercept_TriageGen0Test {

    private ReturnsSmartNulls.ThrowingInterceptor interceptor;
    private Object obj;
    private Method method;
    private Object[] args;
    private MethodProxy proxy;

    @Before
    public void setUp() throws Exception {
        interceptor = new ReturnsSmartNulls.ThrowingInterceptor();
        obj = mock(Object.class);
        method = Object.class.getMethod("toString");
        args = new Object[0];
        proxy = mock(MethodProxy.class);
    }

    @Test
    public void testIntercept_WhenIsToString_ReturnsSmartNullString() throws Throwable {
        // Note: isToString(method) is checked via new ObjectMethodsGuru().isToString(method)
        // Since toString is a standard method, it should trigger the first branch.

        Object result = interceptor.intercept(obj, method, args, proxy);

        // The implementation uses formatMethodCall() which is likely an internal method of the interceptor/outer class.
        // We check if the result starts with the expected prefix.
        String expectedPrefix = "SmartNull returned by unstubbed ";
        String actualResult = (String) result;

        assert(actualResult.startsWith(expectedPrefix));
    }

    @Test
    public void testIntercept_WhenIsNotToString_ReturnsNull() throws Throwable {
        // Create a method that is NOT toString to trigger the second branch
        Method nonToStringMethod = Object.class.getMethod("hashCode");

        Object result = interceptor.intercept(obj, nonToStringMethod, args, proxy);

        assertNull(result);
    }
}
